SourceCode.Declaration:
class TFMBackendIDInstance
{
    TableName       tblName;
    FieldName       fldName;
    TFMOrderTypes   types;
    str             fieldValue;
    }

Method.Source:
public static TFMBackendIDInstance Construct(TFMBackendId _backendId)
{
    return new TFMBackendIDInstance(_backendId);
}

protected void new(TFMBackendId _backendId)
{        
    container		backendCon = TFMHelper::strSplit(_backendId,'/').pack();
    tblName = conPeek(backendCon,4);
    fldName = conPeek(backendCon,5);
    fieldValue = conPeek(backendCon,6);
    types = conLen(backendCon) > 6 ? conPeek(backendCon,7) : '';
}

public TableName parmTableName(TableName   _tblName = tblName)
{
    tblName = _tblName;
    return tblName;
}

public FieldName parmFieldName(FieldName   _fldName = fldName)
{
    fldName = _fldName;
    return fldName;
}

public TFMOrderTypes parmType(TFMOrderTypes   _types = types)
{
    types = _types;
    return types;
}

public str parmFieldValue(str   _fieldValue = fieldValue)
{
    fieldValue = _fieldValue;
    return fieldValue;
}
